// 02b — Filter Active Competitors
// 为什么要单独一步：Google Sheets 读取节点的「筛选」是严格区分大小写的字符串比较，
// 而表里的 active 可能是布尔 TRUE（读出来是 "true"）、大写 "TRUE"、或 "yes"。
// 一旦对不上，它会「静默地」一行都不返回 —— 工作流显示跑成功了，其实什么都没做。
// 放在代码里判断：容忍 true / TRUE / yes / y / 1 / active，并丢掉没填用户名的空行。
const truthy = function (v) {
  if (v === true) return true;
  if (v === false || v === null || v === undefined) return false;
  const s = String(v).trim().toLowerCase();
  return s === 'true' || s === 'yes' || s === 'y' || s === '1' || s === 'active';
};

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const username = String(j.instagram_username || '').trim().replace(/^@/, '');
  if (!username) continue;              // 没填用户名的空行，跳过
  if (!truthy(j.active)) continue;      // 只有 active 为真的才处理
  const n = Number(j.max_reels_per_check);
  out.push({
    json: Object.assign({}, j, {
      instagram_username: username,
      max_reels_per_check: (Number.isFinite(n) && n > 0) ? n : 3
    })
  });
}
return out;

// 05 — Normalize Reel Data
// 把 Discovery Actor 的输出收敛成「每支 Reel 一条」的干净结构。
// Discovery 已开 Actor 的 Reels only 模式（profileContentType='reels'），正常情况下只回 Reels
// （实测：limit=6 时回 6 条，全部 productType=clips）。
// 下面 type==='video' 这层过滤留作安全网：万一上游被换回 all_posts 模式，
// 照片和轮播会被挡在这里，不会白白花掉转写费。
const competitor = $('03 — Loop Over Competitors').item.json;
const maxReels = Math.min(
  Number(competitor.max_reels_per_check) > 0 ? Number(competitor.max_reels_per_check) : 3,
  10
);

const rows = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.success !== true) continue;                 // 失败 item 直接丢
  const c = j.content || {};
  if (c.type !== 'video') continue;                 // 只要视频（照片/carousel 跳过）
  const shortcode = c.shortcode;
  if (!shortcode) continue;

  // competitor 身份：优先用 Competitors 表里的用户名（用户填的），
  // 而不是 inputUrl，避免 URL 形态差异；author.username 作为兜底。
  const username = competitor.instagram_username
    || (j.author && j.author.username)
    || '';

  rows.push({
    json: {
      reel_key: username + ':' + shortcode,
      instagram_username: username,
      shortcode,
      // canonical URL 由我们自己拼 —— 不信任 Actor 给的 normalizedUrl（/p/ 与 /reel/ 会漂）
      reel_url: 'https://www.instagram.com/reel/' + shortcode + '/',
      caption: c.caption || '',
      published_at: c.publishedAt || '',
      duration: (c.durationSeconds === undefined ? null : c.durationSeconds),
      media_type: c.type,
      like_count: (j.engagement && j.engagement.likeCount) ?? null,
      comment_count: (j.engagement && j.engagement.commentCount) ?? null,
      discovered_from: j.inputUrl || '',
      max_reels_per_check: maxReels
    }
  });
}

// 按发布时间倒序 → 取最新 N 条（这也天然满足「第一次运行只处理最近的」）
rows.sort((a, b) => String(b.json.published_at).localeCompare(String(a.json.published_at)));
return rows.slice(0, maxReels);

// 06 — Prepare Reel Queue
// 跨 competitor 的二次去重：两个号可能转发同一支 Reel（collab post 常见）。
// 同一个 reel_key 在同一轮里只能出现一次。
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const k = item.json.reel_key;
  if (!k || seen.has(k)) continue;
  seen.add(k);
  out.push(item);
}
return out;

// 09 — Is New Or Retryable?
// 结合 §E.3 的判定逻辑与注册表记录，决定这条 Reel 该处理还是跳过。
// DataTable 没有唯一约束，所以「先查后写」必须由我们自己做。
const reel = $('07 — Loop Over Reels').item.json;
const found = $input.all().filter(i => i.json && i.json.reel_key === reel.reel_key);

const maxAttempts = 3;
let decision = 'new';
let reason = 'not in registry';

if (found.length > 0) {
  const rec = found[0].json;
  const attempts = Number(rec.attempts) || 0;
  if (rec.status === 'success') {
    decision = 'skip';
    reason = 'already processed successfully';
  } else if (attempts >= maxAttempts) {
    decision = 'dead';
    reason = 'failed and attempts >= ' + maxAttempts;
  } else {
    decision = 'retry';
    reason = 'previous attempt failed, attempts=' + attempts;
  }
}

return [{
  json: Object.assign({}, reel, {
    _decision: decision,
    _reason: reason,
    _attempts: found.length > 0 ? (Number(found[0].json.attempts) || 0) : 0
  })
}];

// 11 — Validate Transcript
// Actor 单条失败会返回一条失败 item（run 仍是 SUCCEEDED），这里把它规范化。
// 实测：不存在的 shortcode → media_not_found / MEDIA_NOT_FOUND / retryable=false
const reel = $('09 — Is New Or Retryable?').item.json;
const items = $input.all().map(i => i.json).filter(j => j && typeof j === 'object');

if (items.length === 0) {
  return [{ json: Object.assign({}, reel, {
    ok: false, error_code: 'NO_ITEM_RETURNED', retryable: true,
    error_message: 'Actor returned no dataset items' }) }];
}

const r = items[0];
const status = r.status || 'error';
const err = r.error || {};
const text = (r.transcript && r.transcript.text) ? String(r.transcript.text).trim() : '';

if (r.success !== true || text === '') {
  // no_speech 表示媒体取到了但没人声，重试通常也没用 → 视为不可重试
  const retryable = (status === 'no_speech') ? false : (err.retryable !== false);
  return [{ json: Object.assign({}, reel, {
    ok: false,
    transcript_status: status,
    error_code: err.code || status.toUpperCase(),
    error_message: err.message || status,
    retryable: retryable,
    // 中文说明：transcript 为空不代表 Reel 无效，但无法做内容分析
    empty_transcript: text === ''
  }) }];
}

const meta = r.media || {};
const content = r.content || {};
return [{ json: Object.assign({}, reel, {
  ok: true,
  transcript_status: status,
  transcript: text,
  transcript_language: (r.transcript && r.transcript.language) || null,
  duration: (content.durationSeconds === undefined ? reel.duration : content.durationSeconds),
  caption: reel.caption || content.caption || '',
  // 媒体链接是临时 CDN（mediaUrlsTemporary），不写进结果表长期保存
  _media_is_temporary: meta.mediaUrlsTemporary === true
}) }];

// 13 — Validate AI Output
// AI 返回的是解析好的对象（chainLlm + json_object），这里做字段兜底。
const reel = $('11 — Validate Transcript').item.json;
const REQUIRED = ['summary','hook','hook_type','topic','content_angle','target_audience',
  'pain_point','key_message','cta','emotion','content_format','why_it_may_work',
  'three_rewritten_hooks','three_content_ideas','language','confidence'];

const raw = $input.first().json || {};
// 有的情况模型会把结果包一层 { output: {...} }
const ai = (raw.output && typeof raw.output === 'object') ? raw.output : raw;

const missing = REQUIRED.filter(k => ai[k] === undefined || ai[k] === null || ai[k] === '');
const asText = v => Array.isArray(v) ? v.filter(Boolean).map(s => '- ' + s).join('\n') : (v == null ? '' : String(v));

return [{ json: Object.assign({}, reel, {
  ai_ok: missing.length === 0,
  ai_missing_fields: missing,
  summary: ai.summary || '',
  hook: ai.hook || '',
  hook_type: ai.hook_type || '',
  topic: ai.topic || '',
  content_angle: ai.content_angle || '',
  target_audience: ai.target_audience || '',
  pain_point: ai.pain_point || '',
  key_message: ai.key_message || '',
  cta: ai.cta || '',
  emotion: ai.emotion || '',
  content_format: ai.content_format || '',
  why_it_may_work: ai.why_it_may_work || '',
  three_rewritten_hooks: asText(ai.three_rewritten_hooks),
  three_content_ideas: asText(ai.three_content_ideas),
  ai_language: ai.language || '',
  confidence: (typeof ai.confidence === 'number') ? ai.confidence : null,
  processed_at: new Date().toISOString()
}) }];

// 17 — Build Run Digest
// 汇总本轮运行，供 Telegram 摘要（或人工查看）。
//
// ⚠️ 这里有两个坑，都不能用裸的 $('节点名').all()：
//
// 坑 1（会打断整个工作流）：节点本轮没执行过时（典型：本轮零失败，
// 「16 — Record Failure」一次都没跑），$('...') 会抛
// "Node 'xxx' hasn't been executed"，摘要节点直接报错。
//
// 坑 2（会漏计数，更隐蔽）：本工作流在循环里逐条处理 Reel，
// 循环每一小批 = 上游节点的一次独立 run。$('节点').all() 不带 runIndex
// 时只返回「最近一次 run」的输出 —— 循环跑了 N 批就只数到最后 1 条。
// （n8n 源码 workflow-data-proxy.js：runIndex 缺省用 defaultReturnRunIndex。）
//
// 解法：按 runIndex 0,1,2,... 逐次枚举，把所有批次加起来。
// 用 $('节点').all(0, r) 显式指定第 r 次 run。三种边界（已对 n8n 2.42.6
// 源码 getNodeExecutionData 逐一核实）：
//   - r 超过实际批次数     → 抛 "Run r of node ... not found"  → 枚举结束
//   - 该批输出 0 条（空批） → 抛 "No data found from `main` input" → 批存在，跳过继续
//   - 节点整轮没跑过       → 抛 "Node '...' hasn't been executed" → 视为空数组
const collectAllRuns = (nodeName) => {
  const out = [];
  for (let r = 0; r < 1000; r++) {
    let items;
    try {
      items = $(nodeName).all(0, r);
    } catch (e) {
      const msg = String((e && e.message) || e);
      if (msg.includes('No data found from `main` input')) continue; // 空批：批存在但 0 条
      break;                                                          // 枚举结束 / 节点没跑过
    }
    if (Array.isArray(items)) out.push(...items);
  }
  return out.map(i => i.json);
};

const all = collectAllRuns('13 — Validate AI Output');
const failed = collectAllRuns('16 — Record Failure');

const ok = all.filter(j => j && j.ai_ok === true);
const degraded = all.filter(j => j && j.ai_ok === false);

const byCompetitor = {};
for (const j of ok) {
  const u = j.instagram_username || '(unknown)';
  byCompetitor[u] = (byCompetitor[u] || 0) + 1;
}

return [{ json: {
  run_at: new Date().toISOString(),
  analyzed: ok.length,
  analyzed_with_missing_fields: degraded.length,
  failed: failed.length,
  by_competitor: byCompetitor,
  note: 'Views/likes are best-effort; Instagram returns null for most engagement fields without login.'
} }];
